def write(path,title,content,description='Personal online tutoring in every subject from primary school to Grade 12 / FSc. For students in the UK, USA, Gulf and beyond.'):
    target=D/path/'index.html' if path else D/'index.html';target.parent.mkdir(parents=True,exist_ok=True)
    page=f'<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f5f4ec"><title>{html.escape(title)} — ProTutors Online</title><meta name="description" content="{html.escape(description)}"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/pages.css"><script src="/app.js" defer></script></head><body data-page="{path or "home"}">{header()}<main id="main">{content}</main>{footer()}</body></html>'
    target.write_text(page)
