write('about','About ProTutors Online',hero('A WORLD OF LEARNING, BUILT AROUND YOU','Small moments.<br><em>Big possibilities.</em>','That moment when a concept clicks. When a question feels less intimidating. When a learner starts to believe they can. That’s the kind of learning we’re here for.','orb','About us')+'<section class="section manifesto" id="explore"><span class="eyebrow">WHY PROTUTORS ONLINE</span><h2>Good learning starts<br>with a simple idea:<br><em>every learner deserves<br>to be understood.</em></h2><div><p>ProTutors Online offers personal tutoring across school subjects, from primary to Grade 12 / FSc. We connect school learning with an approach that leaves room for questions, practice, and a little curiosity.</p><p>Our classroom is online. Our focus is individual. Whether you study in the UK, USA, UAE, Saudi Arabia, Qatar, Oman, or elsewhere, the starting point is the same: your subject, your course, your goals.</p></div></section><section class="section soft-panel">'+sectionheading('WHAT WE VALUE','A little more<br><em>human.</em>')+featuregrid([('Clarity before speed','Take time to understand a concept rather than rush to an answer.'),('Questions are welcome','Make space for learners to say what they do and do not understand.'),('Progress with purpose','Choose the next step using the work in front of us, not a one-size-fits-all script.')])+'</section>'+cta())
write('how-it-works','How online tutoring works',hero('FROM FIRST QUESTION TO NEXT CHAPTER','Simple to start.<br><em>Personal all the way.</em>','Explore your subjects, tell us what you need, and discuss a free introductory demo. Then decide what feels right for your learner.','book','How it works')+'<section class="section" id="explore"><div class="process-list">'+''.join(f'<article class="process-step reveal"><span>0{i+1}</span><div><h2>{t}</h2><p>{p}</p></div><b>{["◎","✦","＋","↗"][i]}</b></article>' for i,(t,p) in enumerate([('Tell us your story.','Share the subject, school level, country, time zone, and goal. Include your course or exam board when you know it.'),('Explore a tutor match.','Discuss your needs and an introductory demo. It is a chance to ask questions and understand how the lesson could work.'),('Agree on your plan.','Choose a subject focus, a suitable schedule, and a lesson arrangement. Confirm fees and practical details before committing.'),('Keep the conversation going.','Use practice and feedback to review understanding. Bring new questions and adjust the lesson focus as school work moves on.')]))+'</div></section><section class="section soft-panel">'+sectionheading('BEFORE YOUR FIRST LESSON','A small checklist.<br><em>A smoother start.</em>')+'<div class="checklist-card"><label><input type="checkbox"> A computer or tablet with a stable connection</label><label><input type="checkbox"> A working microphone and a quiet place</label><label><input type="checkbox"> Your course, textbook, or recent school work</label><label><input type="checkbox"> One question or topic you want to understand</label><p>This checklist stays on this page and is not sent anywhere.</p></div></section>'+cta())
write('progress','Learning & progress',hero('THE LITTLE THINGS THAT ADD UP','See the steps.<br><em>Celebrate the learning.</em>','Progress can look like a clearer explanation, a problem solved independently, or a better question. We look at the learning behind the answer.','orb','Learning & progress')+'<section class="section" id="explore">'+sectionheading('WHAT PROGRESS CAN LOOK LIKE','More than a<br><em>single score.</em>')+featuregrid([('Understanding','Can the learner explain the idea in their own words? Can they connect it to something they already know?'),('Independence','Can they choose an approach and attempt a similar question without being shown every step?'),('Application','Can they use the same idea in a new context, interpret the question, and check their answer?')])+'<div class="progress-demo"><div><span class="eyebrow">ILLUSTRATIVE LEARNING JOURNEY</span><h2>A clearer picture,<br><em>one step at a time.</em></h2><p>A sample of how a tutor might structure a topic review. This is an example, not a student result.</p></div><ol><li><span>01</span><div><h3>Explore the starting point</h3><p>Review a recent question and talk through the reasoning.</p></div></li><li><span>02</span><div><h3>Practise the missing piece</h3><p>Work on a chosen skill with explanation and feedback.</p></div></li><li><span>03</span><div><h3>Return and reflect</h3><p>Try a related question and agree on the next practice goal.</p></div></li></ol></div></section>'+cta())
# JOURNAL: original substantive content, no fake authors or testimonials.
articles=[('a-revision-plan-that-fits','A revision plan that fits your real week.','STUDY HABITS','5 MIN READ','Turn an overwhelming list of topics into a manageable set of next steps.',[
('Start with what is actually ahead.','Write down the subjects you study and the assessments you are preparing for. Add dates when you know them. If a date is uncertain, label it uncertain rather than building the whole plan around it.'),('Make topics small enough to practise.','“Revise chemistry” is hard to act on. “Balance five equations, then check the method” is clearer. Break each subject into tasks with a visible finish.'),('Leave room for feedback.','A plan should include time to check your work. Note the mistake, identify the missing idea, and choose a follow-up question. Ask for help when you cannot explain why the correction works.'),('Keep the plan realistic.','Start with the time you can actually protect around school, meals, family, and rest. Leave spare space for homework or topics that take longer than expected. A missed session is a reason to adjust, not abandon, the plan.'),('Review the next step.','At the end of the week, ask which topics became clearer and which still need attention. Carry unfinished tasks forward intentionally. Use that information to choose what you and your tutor work on next.')]),('getting-ready-for-online-tutoring','Make your first online lesson count.','FOR PARENTS','4 MIN READ','A few simple preparations can make the first conversation more useful.',[('Bring a starting point.','A recent worksheet, textbook page, or tricky question gives the tutor something concrete to discuss. It does not need to be perfect or complete.'),('Share the course, not just the subject.','Chemistry can mean very different work at different levels. Provide the school year, syllabus, and exam board where available. If you do not know the board, share the course name or school outline.'),('Talk about the goal.','Would your learner like help understanding a topic, building confidence, or preparing for an assessment? A clear immediate goal gives the lesson focus while leaving room for the tutor to explore the foundations.'),('Check the practical details.','Test your device, microphone, and connection. Keep school materials nearby and choose a place where the learner can hear and be heard.'),('Ask what comes next.','Before arranging further lessons, discuss the proposed focus, lesson duration, schedule, fees, and feedback. A demo is a conversation about fit, not an obligation to continue.')]),('choosing-curriculum-support','Choose support for the course you actually study.','CURRICULUM CLARITY','4 MIN READ','Location is part of your enquiry. Your school syllabus is the other part.',[('Country and curriculum are different questions.','A student in Dubai may follow a British, American, IB, Pakistan, or another school course. Start with the course listed by your school rather than assume your location determines it.'),('Check the level and subject.','Include the year group or grade and the subject’s full name. At higher levels, specify any course level or option your school uses.'),('Bring the school’s materials.','An outline, topic list, or recent assignment helps a tutor understand what you are learning now. It also helps separate an unfamiliar explanation from a genuinely new topic.'),('Match the immediate need.','Some students need foundations. Others want practice with longer questions or revision of a particular unit. Explain the difficulty using an example where possible.'),('Confirm before committing.','Ask whether a suitable tutor is available for your exact course and time zone. Share the details again when arranging lessons so the plan begins with the right information.')])]
write('journal','The study journal',hero('NOTES FOR YOUR NEXT CHAPTER','A little insight.<br><em>A clearer way forward.</em>','Practical reading for students and parents: study habits, online learning, and choosing the right course support.','book','Study journal')+'<section class="section" id="explore"><div class="journal-grid">'+''.join(f'<a href="/journal/{a[0]}/" class="journal-card reveal tilt-card"><div class="journal-cover cover-{i}"><span>{["PLAN.<br>PRACTISE.<br>REFLECT.","YOUR FIRST<br><em>aha!</em>","YOUR COURSE.<br>YOUR<br><em>direction.</em>"][i]}</span><b>{["↗","✳","◎"][i]}</b></div><span>{a[2]} · {a[3]}</span><h3>{a[1]}</h3><p>{a[4]}</p><b>Read the story ↗</b></a>' for i,a in enumerate(articles))+'</div></section>'+cta())
